    desc: 'Koníčky, šport, dohadovanie stretnutí, pozvánky a výlety.',
    phrases: [
      { id: 'freetime-p1', de: 'Hast du am Wochenende schon was vor?', sk: 'Máš už na víkend niečo v pláne?', note: 'vor|haben – predpona na konci', reg: 'informal' },
      { id: 'freetime-p2', de: 'Hast du Lust, ins Kino zu gehen?', sk: 'Máš chuť ísť do kina?', note: 'Lust haben + zu + infinitív; in + das = ins', reg: 'informal' },
      { id: 'freetime-p3', de: 'Wie wär’s mit Samstag?', sk: 'Čo tak sobota?', note: 'wär’s = wäre es (Konjunktiv II)', reg: 'informal' },
      { id: 'freetime-p4', de: 'Klingt gut!', sk: 'Znie to dobre!', reg: 'informal' },
      { id: 'freetime-p5', de: 'Da kann ich leider nicht.', sk: 'Vtedy, žiaľ, nemôžem.', reg: 'neutral' },
      { id: 'freetime-p6', de: 'Passt dir Freitag um sieben?', sk: 'Hodí sa ti piatok o siedmej?', note: 'passen + Dativ (dir)', reg: 'informal' },
      { id: 'freetime-p7', de: 'Wo treffen wir uns?', sk: 'Kde sa stretneme?', reg: 'neutral' },
      { id: 'freetime-p8', de: 'Ich hol dich ab.', sk: 'Vyzdvihnem ťa.', note: 'ab|holen – predpona na konci', reg: 'informal' },
      { id: 'freetime-p9', de: 'Sollen wir lieber was anderes machen?', sk: 'Nemáme radšej robiť niečo iné?', reg: 'informal' },
      { id: 'freetime-p10', de: 'Ich bin dabei!', sk: 'Idem do toho!', reg: 'informal' },
      { id: 'freetime-p11', de: 'Können wir das auf nächste Woche verschieben?', sk: 'Môžeme to presunúť na budúci týždeň?', note: 'verschieben auf + Akkusativ', reg: 'neutral' },
      { id: 'freetime-p12', de: 'Was machst du so in deiner Freizeit?', sk: 'Čo robievaš vo voľnom čase?', reg: 'informal' },
      { id: 'freetime-p13', de: 'Ich gehe zweimal die Woche joggen.', sk: 'Dvakrát týždenne chodím behať.', note: 'gehen + infinitív na konci: joggen gehen', reg: 'neutral' },
      { id: 'freetime-p14', de: 'Ich interessiere mich für Fotografie.', sk: 'Zaujímam sa o fotografiu.', note: 'sich interessieren für + Akkusativ', reg: 'neutral' },
      { id: 'freetime-p15', de: 'Ich hab ewig nicht mehr Tennis gespielt.', sk: 'Už celú večnosť som nehral tenis.', reg: 'informal' },
      { id: 'freetime-p16', de: 'Ich lade dich zu meinem Geburtstag ein.', sk: 'Pozývam ťa na moje narodeniny.', note: 'ein|laden zu + Dativ', reg: 'informal' },
      { id: 'freetime-p17', de: 'Soll ich was mitbringen?', sk: 'Mám niečo priniesť?', reg: 'informal' },
      { id: 'freetime-p18', de: 'Danke für die Einladung, ich komme gern!', sk: 'Ďakujem za pozvanie, rád prídem!', reg: 'neutral' },
      { id: 'freetime-p19', de: 'Ich schaff’s leider nicht.', sk: 'Žiaľ, nestihnem to.', reg: 'informal' },
      { id: 'freetime-p20', de: 'Ich sag dir noch Bescheid.', sk: 'Ešte ti dám vedieť.', note: 'Bescheid sagen + Dativ (dir)', reg: 'informal' }
    ],
